<template>
  <div class="login-container d-flex align-items-center justify-content-center">
    <b-card class="login-card shadow-sm border-0 p-4">
      <div class="text-center mb-4">
        <img
          src="@/assets/logo-mbr.jpg"
          alt="MBR Microcrédito"
          class="img-fluid logo-img mb-2"
        />
        <h4 class="text-secondary font-weight-bold">Bem-vindo</h4>
        <p class="text-muted small">Acesse sua conta para continuar</p>
      </div>

      <b-form @submit.prevent="submit">
        <b-form-group
          id="input-group-email"
          label="E-mail"
          label-for="email"
          class="mb-3"
        >
          <b-input-group>
            <template #prepend>
              <b-input-group-text class="bg-light border-right-0">
                <b-icon icon="envelope-fill" variant="secondary"></b-icon>
              </b-input-group-text>
            </template>
            <b-form-input
              id="email"
              v-model="form.email"
              placeholder="E-mail ou nº de telemóvel"
              required
              class="border-left-0"
            ></b-form-input>
          </b-input-group>
        </b-form-group>

        <b-form-group
          id="input-group-pass"
          label="Senha"
          label-for="password"
          class="mb-4"
        >
          <b-input-group>
            <template #prepend>
              <b-input-group-text class="bg-light border-right-0">
                <b-icon icon="lock-fill" variant="secondary"></b-icon>
              </b-input-group-text>
            </template>
            <b-form-input
              id="password"
              v-model="form.password"
              type="password"
              placeholder="Digite sua senha"
              required
              class="border-left-0"
            ></b-form-input>
          </b-input-group>
        </b-form-group>

        <b-button
          type="submit"
          block
          class="btn-mbr text-uppercase font-weight-bold py-2 mb-2"
          :disabled="isLoading"
        >
          <span v-if="isLoading">Carregando...</span>
          <span v-else>Entrar</span>
        </b-button>

        <b-button
          variant="outline-secondary"
          block
          class="text-uppercase font-weight-bold py-2"
          @click="loginAsMutuario"
        >
          Entrar como Mutuário
        </b-button>
      </b-form>

      <div class="text-center mt-4">
        <small class="text-muted">&copy; MBR Microcrédito</small>
      </div>
    </b-card>
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import logs from "@/utils/logs";
import axios from "axios";

export default {
  data: () => ({
    form: {
      email: "",
      password: "",
    },
  }),

  computed: {
    ...mapGetters(["isLoading", "user", "isLoggedIn", "success"]),
  },

  watch: {
    user: function () {
      setTimeout(() => {
        if (this.user.userRole === 3) {
          this.$router.replace("/gestor");
        } else if (this.user.userRole >= 1) {
          this.$router.replace("/dashboard");
        } else if (this.user.userRole === 0) {
          this.$store.commit("SET_PASSWORD_STATUS", this.user.updatedPassword);
          this.$router.replace("/company");
        }
      }, 500);
    },
  },

  created() {
    if (this.user.userRole === 3) {
      this.$router.replace("/gestor");
    } else if (this.user.userRole >= 1) {
      this.$router.replace("/dashboard");
    } else if (this.user.userRole === 0) {
      this.$router.replace("/company");
    }
  },

  methods: {
    submit() {
      const email = (this.form.email || "").trim();
      const password = (this.form.password || "").trim();

      if (!email) {
        this.showToast("Atenção!", "warning", "Insira o e-mail ou nº de telemóvel.");
        return;
      }
      if (!password) {
        this.showToast("Atenção!", "warning", "Insira a senha.");
        return;
      }

      this.$store
        .dispatch("actionDoLogin", { email, password })
        .then(() => {
          const logsParams = logs(
            this.user,
            `${email} - ${this.user.name} autenticado com sucesso.`,
            "Autenticação"
          );
          this.$store.dispatch("addLog", logsParams);
          this.showToast("", "success", this.success);
        })
        .catch(() => {
          this.showToast("Erro!", "danger", this.success);
        });
    },

    // Método para tratar o Login do Mutuário
    async loginAsMutuario() {
      const phone = (this.form.email || "").trim();
      const password = (this.form.password || "").trim();

      if (!phone) {
        this.showToast("Atenção!", "warning", "Insira o nº de telemóvel.");
        return;
      }
      if (!password) {
        this.showToast("Atenção!", "warning", "Insira a senha.");
        return;
      }

      this.$store.commit("LOADING_STATUS", true);
      axios
        .post(`/api/customer/login/`, {
          phone,
          password,
        }, { timeout: 10000 })
        .then((res) => {
          if (res.data.success) {
            const customer = res.data.result[0];
            const token = res.data.token;

            // Guardar token e dados do cliente no localStorage
            localStorage.setItem("applicationMicroToken", token);
            localStorage.setItem("customer", JSON.stringify(customer));
            localStorage.setItem("isCustomerSession", "true");

            // Definir header de autenticação no axios
            axios.defaults.headers.common[
              "Authorization"
            ] = `Bearer ${token}`;

            // Actualizar Vuex state (token + dados do cliente)
            this.$store.commit("AUTH_SUCCESS", { ...customer, token });
            this.$store.commit("SET_CUSTOMER_PANEL", customer);
            this.$store.commit("SET_IS_CUSTOMER_SESSION", true);

            this.$router.replace("/customer-dashboard");
            this.showToast("", "success", "Login realizado com sucesso");
          } else {
            this.$store.commit("SET_CUSTOMER_PANEL", {});
            this.showToast("Erro!", "danger", res.data.message);
          }
        })
        .catch(() => {
          this.$store.commit("SET_CUSTOMER_PANEL", {});
          this.showToast("Erro!", "danger", "Erro ao fazer login");
        })
        .finally(() => {
          this.$store.commit("LOADING_STATUS", false);
        });
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(`${msg}`, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 2000,
      });
    },
  },
};
</script>

